    private int livingNeighborCount(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (livingCells.contains(new Cell(cell.x() + dx, cell.y() + dy))) {
